code_examples.text:
when HTTP_REQUEST {
  if { [HTTP::uri] contains "/secure/" } {
    pool ssl_pool
  } else {
    pool http_pool
  }
}
when SERVER_CONNECTED {
  if {[TCP::remote_port] != 443} {
    SSL::disable
  }
}

when CLIENT_ACCEPTED {
  set cmd "set remote_port [TCP::remote_port]"
  eval $cmd
  log local0. "Remote port is: $remote_port"
}
